package com.robertwoolbright.inventory.inventory.error

import org.springframework.http.HttpStatus
import org.springframework.http.MediaType
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.ExceptionHandler
import org.springframework.web.bind.annotation.RestControllerAdvice

/** Where the various custom build exceptions are built out for spring to catch. */
// Why: RestController advise so spring will catch and throw specific exceptions we have built out.
@RestControllerAdvice
class InventoryExceptionHandler{

    // Contract: paths./inventory/{skuId}.get - 404 with text/plain when SkuNotFoundException is thrown.
    
    /** Builds out the sku not found exception for spring to handle. */
    @ExceptionHandler(SkuNotFoundException::class)
    fun inventoryExceptionHandler(ex: SkuNotFoundException ): ResponseEntity<String> = 
        
        ResponseEntity.status(HttpStatus.CONFLICT)
            .contentType(MediaType.TEXT_PLAIN)
            .body(ex.message ?: "No response from sku not found exception.")
    
}

